const fs = require('fs');

/**
 * Read every file in `paths` and return their combined text content,
 * joined with a single newline between files.
 */
function combineFiles(paths) {
  let combined = '';
  for (const p of paths) {
    combined += fs.readFileSync(p) + '\n';
  }
  return combined.trimEnd();
}

module.exports = { combineFiles };

